import{_ as e,o as a,c as r,ag as n}from"./chunks/framework.DaCm-iTo.js";const m=JSON.parse('{"title":"EmakiStrengthen","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/strengthen/index.md","filePath":"en/modules/strengthen/index.md","lastUpdated":null}'),s={name:"en/modules/strengthen/index.md"};function i(d,t,o,l,c,h){return a(),r("div",null,[...t[0]||(t[0]=[n(`<h1 id="emakistrengthen" tabindex="-1">EmakiStrengthen <a class="header-anchor" href="#emakistrengthen" aria-label="Permalink to &quot;EmakiStrengthen&quot;">​</a></h1><p>EmakiStrengthen provides star-based equipment strengthening, temper state, protection materials, branch trees, attribute output, strengthen layer rebuilding, and a public API.</p><blockquote><p>Some commands still use the historical <code>crack</code> naming (such as <code>clearcrack</code>); gameplay documentation refers to it consistently as &quot;temper&quot;.</p></blockquote><h2 id="module-facts" tabindex="-1">Module facts <a class="header-anchor" href="#module-facts" aria-label="Permalink to &quot;Module facts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Value</th></tr></thead><tbody><tr><td>Module version</td><td><code>4.6.4</code></td></tr><tr><td>Main command</td><td><code>/emakistrengthen</code></td></tr><tr><td>Alias</td><td><code>/estrengthen</code></td></tr><tr><td>Hard dependency</td><td>EmakiCoreLib</td></tr><tr><td>Soft dependency</td><td>EmakiItem, EmakiAttribute, PlaceholderAPI</td></tr><tr><td>Main permissions</td><td><code>emakistrengthen.use</code>, <code>emakistrengthen.reload</code>, <code>emakistrengthen.debug</code>, <code>emakistrengthen.admin</code></td></tr></tbody></table><h2 id="pages" tabindex="-1">Pages <a class="header-anchor" href="#pages" aria-label="Permalink to &quot;Pages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Contents</th></tr></thead><tbody><tr><td><a href="./commands.html">Commands</a></td><td>Opening the strengthen GUI, inspecting the held item, refreshing display, setting stars, and giving materials.</td></tr><tr><td><a href="./recipes.html">Recipes</a></td><td>Success rates, material costs, failure penalties, effects, and actions in <code>recipes/*.yml</code>.</td></tr><tr><td><a href="./process.html">Process</a></td><td>The full strengthen flow from recipe matching to PDC writes and display refresh.</td></tr><tr><td><a href="./branch.html">Branch Trees</a></td><td>Strengthen routes per star range and the attributes, skills, and display each route grants.</td></tr><tr><td><a href="./broadcast.html">Broadcast</a></td><td>Notifying nearby or all players the first time a star tier is reached.</td></tr><tr><td><a href="./placeholders.html">Placeholders</a></td><td>PlaceholderAPI output.</td></tr><tr><td><a href="./corelib-actions.html">CoreLib Actions</a></td><td>Rebuilding and modifying the main-hand strengthen layer.</td></tr><tr><td><a href="./api.html">API</a></td><td>Reading state, previewing, and executing strengthening through <code>EmakiStrengthenApi</code>.</td></tr><tr><td><a href="./events.html">Event API</a></td><td>Bukkit events and interception points across the strengthen flow.</td></tr></tbody></table><h2 id="core-concepts" tabindex="-1">Core concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core concepts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concept</th><th>Description</th></tr></thead><tbody><tr><td>Strengthen star</td><td>Current strengthen tier of the item, such as +1, +2, or +10.</td></tr><tr><td>Strengthen recipe</td><td>Defines which items can be strengthened, required materials, success rate, and results.</td></tr><tr><td>Material plan</td><td>Checks and consumes strengthen materials, protection materials, and temper materials.</td></tr><tr><td>Temper</td><td>A level accumulated on failure that raises later success rates by <code>temper_chance_bonus_per_level</code>.</td></tr><tr><td>Failure downgrade</td><td>When the target star is 6 or higher and no protection material is used, failure drops one star.</td></tr><tr><td>Protection material</td><td>A material with <code>protection: true</code> that prevents a star drop on failure.</td></tr><tr><td>Branch tree</td><td>Forks into different strengthen routes after a configured star.</td></tr><tr><td>Strengthen layer</td><td>Writes to the item&#39;s strengthen namespace layer and is rebuilt by CoreLib.</td></tr></tbody></table><h2 id="default-runtime-folder" tabindex="-1">Default runtime folder <a class="header-anchor" href="#default-runtime-folder" aria-label="Permalink to &quot;Default runtime folder&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plugins/EmakiStrengthen/</span></span>
<span class="line"><span>├── config.yml</span></span>
<span class="line"><span>├── recipes/</span></span>
<span class="line"><span>│   ├── example_recipe.yml</span></span>
<span class="line"><span>│   └── example_branch_recipe.yml</span></span>
<span class="line"><span>├── gui/</span></span>
<span class="line"><span>│   └── strengthen_gui.yml</span></span>
<span class="line"><span>└── lang/</span></span>
<span class="line"><span>    ├── zh_CN.yml</span></span>
<span class="line"><span>    └── en_US.yml</span></span></code></pre></div><p><code>recipes/</code> defines the strengthen rules for different items; <code>gui/strengthen_gui.yml</code> defines the layout of the strengthen interface.</p><h2 id="typical-strengthen-flow" tabindex="-1">Typical strengthen flow <a class="header-anchor" href="#typical-strengthen-flow" aria-label="Permalink to &quot;Typical strengthen flow&quot;">​</a></h2><ol><li>Open the strengthen GUI with <code>/estrengthen open</code>.</li><li>Insert target equipment, strengthen materials, and optional protection materials.</li><li>Match an available recipe through the recipe <code>match</code> rules.</li><li>Check conditions, materials, economy costs, and the current star limit.</li><li>Calculate the success rate: target-star base rate plus temper bonus, clamped to <code>success_chance_cap</code>.</li><li>Fire <code>StrengthenPreAttemptEvent</code>, allowing external code to adjust the rate or cancel.</li><li>Roll the outcome and charge materials and costs.</li><li>On success, raise the star by one, write the strengthen layer, and run that star&#39;s <code>actions.success</code>.</li><li>On failure, accumulate temper and possibly drop a star, then run <code>actions.failure</code>.</li><li>CoreLib rebuilds the item presentation; reaching a broadcast star for the first time sends a local or global broadcast.</li></ol><h2 id="relation-with-attribute" tabindex="-1">Relation with Attribute <a class="header-anchor" href="#relation-with-attribute" aria-label="Permalink to &quot;Relation with Attribute&quot;">​</a></h2><p>Strengthen can run as a display-and-progression system only. With <code>ea_attribute</code> effects configured and EmakiAttribute installed, each star can contribute real stats: attributes are written through the EmakiAttribute authoritative API into a structured PDC layer and participate in real combat calculation.</p><p>When EmakiAttribute is absent, Strengthen takes a no-op path: strengthening still completes but no attributes are written.</p><h2 id="relation-with-item" tabindex="-1">Relation with Item <a class="header-anchor" href="#relation-with-item" aria-label="Permalink to &quot;Relation with Item&quot;">​</a></h2><p>With EmakiItem installed, Strengthen registers an item layer preview provider through <code>EmakiItemApi</code> from its conditionally loaded integration package, letting EmakiItem preview strengthen layer content. When EmakiItem is absent or disabled, that registration is skipped or released automatically without affecting strengthening.</p>`,19)])])}const u=e(s,[["render",i]]);export{m as __pageData,u as default};
